begin;
create temp table admin_ids(kind text,id uuid);grant select,insert,update on admin_ids to authenticated;
insert into admin_ids values('tenant',gen_random_uuid()),('owner',gen_random_uuid()),('member',gen_random_uuid());
insert into family_private.tenants(id,code,name,status,contact_phone,contact_email,payment_status,trial_started_at,trial_ends_at)select id,'ADMIN-TEST','اختبار إدارة العائلة','active','+966500009911','owner-admin@example.invalid','unpaid',now(),now()+interval '30 days'from admin_ids where kind='tenant';
select set_config('request.jwt.claim.sub',(select user_id::text from family_private.platform_admins limit 1),true);
select public.platform_action('save',jsonb_build_object('id',(select id from admin_ids where kind='tenant'),'status','active','payment_status','unpaid'));
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_user_meta_data)select id,'authenticated','authenticated','owner-admin@example.invalid',now(),jsonb_build_object('family_code','ADMIN-TEST','display_name','احمد علي حسن اختبار','full_name','احمد علي حسن اختبار','phone','+966500009911','gender','male')from admin_ids where kind='owner';
select set_config('request.jwt.claim.sub',(select id::text from admin_ids where kind='owner'),true);
set local role authenticated;
select public.family_admin('overview');
select public.family_admin('member_add','{"full_name":"صالح احمد علي اختبار","phone":"+966500009912","email":"member-admin@example.invalid","gender":"male","role":"journalist"}');
reset role;
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_user_meta_data)select id,'authenticated','authenticated','member-admin@example.invalid',now(),jsonb_build_object('family_code','ADMIN-TEST','display_name','صالح احمد علي اختبار','full_name','صالح احمد علي اختبار','phone','+966500009912','gender','male')from admin_ids where kind='member';
do $$begin if not exists(select 1 from public.profiles where id=(select id from admin_ids where kind='member')and role='journalist'and status='active')then raise exception 'manual member not claimed';end if;end$$;
select set_config('request.jwt.claim.sub',(select user_id::text from family_private.platform_admins limit 1),true);
set local role authenticated;
insert into admin_ids values('request',(public.platform_action('maintenance_request',jsonb_build_object('id',(select id from admin_ids where kind='tenant'),'reason','اختبار صيانة لوحة الإدارة','hours',4))->>'id')::uuid);
do $$begin begin perform public.family_admin('overview',jsonb_build_object('maintenance',(select id from admin_ids where kind='request')));raise exception 'BYPASS';exception when raise_exception then if sqlerrm='BYPASS'then raise;end if;end;end$$;
reset role;
select set_config('request.jwt.claim.sub',(select id::text from admin_ids where kind='owner'),true);
set local role authenticated;
select public.maintenance_action('approve',jsonb_build_object('id',(select id from admin_ids where kind='request'),'hours',4));
reset role;
do $$begin if not exists(select 1 from family_private.maintenance_requests where id=(select id from admin_ids where kind='request')and expires_at=now()+interval '4 hours')then raise exception 'wrong hours';end if;end$$;
select set_config('request.jwt.claim.sub',(select user_id::text from family_private.platform_admins limit 1),true);
set local role authenticated;
select public.family_admin('settings',jsonb_build_object('maintenance',(select id from admin_ids where kind='request'),'settings',jsonb_build_object('chat_enabled',false)));
reset role;
select set_config('request.jwt.claim.sub',(select id::text from admin_ids where kind='owner'),true);
set local role authenticated;
select public.maintenance_action('revoke',jsonb_build_object('id',(select id from admin_ids where kind='request')));
reset role;
select set_config('request.jwt.claim.sub',(select user_id::text from family_private.platform_admins limit 1),true);
set local role authenticated;
do $$begin begin perform public.family_admin('overview',jsonb_build_object('maintenance',(select id from admin_ids where kind='request')));raise exception 'REVOKED_BYPASS';exception when raise_exception then if sqlerrm='REVOKED_BYPASS'then raise;end if;end;end$$;
reset role;
-- Trial writes stop at 30 days; deletion starts only after the extra 30 days.
update family_private.tenants set trial_started_at=now()-interval '31 days',trial_ends_at=now()-interval '1 day'where id=(select id from admin_ids where kind='tenant');
do $$begin if family_private.tenant_writable((select id from admin_ids where kind='tenant'))then raise exception 'expired trial writable';end if;end$$;
select public.lifecycle_backend('tick');
do $$begin if exists(select 1 from family_private.tenant_deletions where tenant_id=(select id from admin_ids where kind='tenant'))then raise exception 'early deletion';end if;end$$;
update family_private.tenants set trial_started_at=now()-interval '61 days',trial_ends_at=now()-interval '31 days'where id=(select id from admin_ids where kind='tenant');
select public.lifecycle_backend('tick');
select public.lifecycle_backend('files',jsonb_build_object('tenant',(select id from admin_ids where kind='tenant')));
select public.lifecycle_backend('purge_data',jsonb_build_object('tenant',(select id from admin_ids where kind='tenant')));
delete from auth.users where id in(select id from admin_ids where kind in('member','owner'));
select public.lifecycle_backend('finish',jsonb_build_object('tenant',(select id from admin_ids where kind='tenant')));
do $$begin if exists(select 1 from family_private.tenants where code='ADMIN-TEST')then raise exception 'purge incomplete';end if;end$$;
select 'PASS: manual membership verified claim, tenant scope, timed maintenance/revocation, trial write cutoff, exact grace and full scoped purge' result;
rollback;
